+import java.util.Arrays;
+import java.util.Comparator;
+
+public final class BubbleSortTest {
+
+    private BubbleSortTest() {
+    }
+
+    public static void main(String[] args) {
+        testPrimitiveSort();
+        testGenericSort();
+        testCustomComparator();
+        testNoOpCases();
